    }
  } catch (e) {
    console.log(`通知寫入失敗: ${e.message}`);
  }
}

// 如果今天已蒸餾，直接結束
if (fs.existsSync(PROFILE)) {
  const existing = fs.readFileSync(PROFILE, 'utf8');
  if (existing.includes(`蒸餾 ${dateStr}`)) {
    console.log(`${dateStr} 已蒸餾，結束`);
